#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

static long long gcdll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    long long N, K;
    if (scanf("%lld %lld", &N, &K) != 2) return 0;

    long long ans = 0;

    for (long long t = 0; t < N; t++) {
        long long g = gcdll(N, t);
        long long L = N / g;                 // cycle length of rotation by t
        long long cycles = g;                // number of cycles

        long long fixed_cycles;
        if (L % 2 == 0) {
            fixed_cycles = cycles;
        } else {
            fixed_cycles = (cycles + 1) / 2;
        }

        ans += mod_pow(K, fixed_cycles);
        if (ans >= MOD) ans -= MOD;
    }

    ans = (ans * mod_pow(N % MOD, MOD - 2)) % MOD;
    printf("%lld\n", ans);
    return 0;
}

