#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, K;
    cin >> N >> K;

    // A sequence obtainable after rotating some palindrome must satisfy:
    // there exists a cut such that the sequence becomes a palindrome.
    //
    // Let s be such a sequence, and define t_i = s_i - s_{i+1} mod N idea is not needed.
    // The key characterization is:
    // s can be obtained iff s_i = s_{c-i} for some c (indices mod N),
    // i.e. s is fixed by a reflection of the cycle.
    //
    // Number of colorings of an N-cycle with K colors fixed by some reflection:
    //
    // If N is odd:
    //   every reflection fixes exactly (N+1)/2 positions-orbits,
    //   and all reflections are equivalent.
    //   So answer = K^((N+1)/2).
    //
    // If N is even:
    //   reflections are of two types:
    //   - through opposite vertices: fixed set count = N/2 + 1
    //   - through opposite edges:    fixed set count = N/2
    //   We need the union of these two sets.
    //   Their intersection is exactly the sequences fixed by the rotation by 2,
    //   i.e. period 2 sequences, count = K^gcd(N,2) = K^2.
    //   Thus answer = K^(N/2+1) + K^(N/2) - K^2.
    //   For N=2, this still gives K^2.
    //
    // For N=1, answer = K.

    long long ans;
    if (N % 2 == 1) {
        ans = modpow(K, (N + 1) / 2);
    } else {
        long long a = modpow(K, N / 2 + 1);
        long long b = modpow(K, N / 2);
        long long c = modpow(K, 2);
        ans = (a + b - c) % MOD;
        if (ans < 0) ans += MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

