import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long N = fs.nextLong();
        long K = fs.nextLong();

        long ans;
        if ((N & 1L) == 1L) {
            // N odd: every obtainable sequence must itself be a palindrome
            // Count of palindromes of length N over alphabet size K
            ans = modPow(K, (N + 1) / 2);
        } else {
            // N even:
            // A sequence is obtainable iff it has period d where d | N and N/d is odd.
            // For each such d, primitive blocks of length d that are palindromes.
            // Count by Möbius inversion on odd divisors.
            long m = N;
            while ((m & 1L) == 0L) m >>= 1; // odd part of N

            ArrayList<Long> divisors = getDivisors(m);
            Collections.sort(divisors);

            HashMap<Long, Long> primitiveCount = new HashMap<>();
            long total = 0;

            for (long t : divisors) {
                // t is odd divisor of m
                long d = N / t; // candidate period, and t = N/d is odd
                long allPalBlocks = modPow(K, (d + 1) / 2); // palindromes of length d

                long sub = 0;
                for (long t2 : divisors) {
                    if (t2 >= t) break;
                    if (t % t2 == 0) {
                        sub += primitiveCount.get(t2);
                        if (sub >= MOD) sub -= MOD;
                    }
                }
                long cur = (allPalBlocks - sub) % MOD;
                if (cur < 0) cur += MOD;
                primitiveCount.put(t, cur);

                total += cur;
                if (total >= MOD) total -= MOD;
            }
            ans = total;
        }

        System.out.println(ans % MOD);
    }

    static ArrayList<Long> getDivisors(long n) {
        ArrayList<Long> small = new ArrayList<>();
        ArrayList<Long> large = new ArrayList<>();
        for (long i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                small.add(i);
                if (i * i != n) large.add(n / i);
            }
        }
        Collections.reverse(large);
        small.addAll(large);
        return small;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys

MOD = 10**9 + 7

def mod_pow(a, e, mod):
    res = 1
    while e:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def mobius_sieve(n):
    mu = [0] * (n + 1)
    primes = []
    is_comp = [False] * (n + 1)
    mu[1] = 1
    for i in range(2, n + 1):
        if not is_comp[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > n:
                break
            is_comp[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]
    return mu

def divisors(n):
    res = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            res.append(i)
            if i * i != n:
                res.append(n // i)
        i += 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    N, K = map(int, data)

    mu = mobius_sieve(N)

    # g(d): number of palindromes of length d over alphabet size K
    # g(d) = K^ceil(d/2)
    g = [0] * (N + 1)
    for d in divisors(N):
        g[d] = mod_pow(K, (d + 1) // 2, MOD)

    # f(d): number of primitive palindromic strings of length d
    # g(d) = sum_{e|d} f(e)
    # so f(d) = sum_{e|d} mu(d/e) * g(e)
    # Number of obtainable sequences = sum_{d|N} f(d)
    ans = 0
    for d in divisors(N):
        total = 0
        for e in divisors(d):
            total += mu[d // e] * g[e]
        ans = (ans + total) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
